-- 전수 확인: 표현 328개(레벨 그룹별 119/120/89)가 전부 들어가야 한다.
DO $$
BEGIN
    IF (SELECT count(*) FROM writing_expression
        WHERE scenario_id BETWEEN 41 AND 70
          AND id BETWEEN 4001 AND 4328) <> 328 THEN
        RAISE EXCEPTION 'writing_expression 41~70 insert verification failed';
    END IF;
    IF (SELECT count(*) FROM writing_expression
        WHERE scenario_id BETWEEN 41 AND 70 AND difficulty_level = 1) <> 119
       OR (SELECT count(*) FROM writing_expression
        WHERE scenario_id BETWEEN 41 AND 70 AND difficulty_level IN (2, 3)) <> 120
       OR (SELECT count(*) FROM writing_expression
        WHERE scenario_id BETWEEN 41 AND 70 AND difficulty_level = 4) <> 89 THEN
        RAISE EXCEPTION 'writing_expression 41~70 difficulty distribution verification failed';
    END IF;
END
$$;
